const VOLAND_BASE_CLOTHING_IDS = ['helmet-bw-lvl1','amulet-bw-lvl1','armor-bw-lvl1','gloves-bw-lvl1','boots-bw-lvl1','ring1-bw-lvl1','ring2-bw-lvl1','earring1-bw-lvl1','earring2-bw-lvl1'];

const VOLAND_HERO_WEAPON_TYPE = {
  'archer-f':'bow','archer-m':'bow',
  'mage-f-new':'staff','archmage-m':'staff','necro-f-new':'staff','necro-m':'staff',
  'warrior-f':'sword','warrior-m':'sword'
};
const VOLAND_CLASS_WEAPON_MAP = { archer:['bow'], mage:['staff'], warrior:['sword','shield'], tank:['sword','shield'] };
function VOLAND_GET_HERO_CLASS(heroId){ const t=VOLAND_HERO_WEAPON_TYPE[heroId]; if(t==='bow')return'archer'; if(t==='staff')return'mage'; return'warrior'; }
function VOLAND_GET_STARTER_GEAR_FOR_HERO(heroId){
  const cls=VOLAND_GET_HERO_CLASS(heroId);
  const gear=[...VOLAND_BASE_CLOTHING_IDS];
  if(cls==='archer')gear.push('bow-bw-lvl1');
  else if(cls==='mage')gear.push('staff-bw-lvl1');
  else gear.push('sword-bw-lvl1','shield-bw-lvl1');
  return gear;
}
function VOLAND_GET_ALLOWED_WEAPON_BASES(heroId){ return VOLAND_CLASS_WEAPON_MAP[VOLAND_GET_HERO_CLASS(heroId)]||[]; }

